create or replace function public.enforce_document_team()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if not exists (
      select 1
      from public.team_members
      where team_id = new.team_id
        and user_id = auth.uid()
        and role = 'editor'
    ) then
      raise exception 'Not allowed to create document in this team';
    end if;
    if new.created_by is distinct from auth.uid() then
      raise exception 'created_by must be the current user';
    end if;
  elsif tg_op = 'UPDATE' then
    if not exists (
      select 1
      from public.team_members
      where team_id = new.team_id
        and user_id = auth.uid()
        and role = 'editor'
    ) then
      raise exception 'Not allowed to update document in this team';
    end if;
    if new.team_id is distinct from old.team_id then
      raise exception 'team_id cannot be changed';
    end if;
    if not exists (
      select 1
      from public.team_members
      where team_id = new.team_id
        and user_id = auth.uid()
        and role = 'editor'
    ) then
      raise exception 'Document must belong to a team where the user is an editor';
    end if;
  elsif tg_op = 'DELETE' then
    if not exists (
      select 1
      from public.team_members
      where team_id = old.team_id
        and user_id = auth.uid()
        and role = 'editor'
    ) then
      raise exception 'Not allowed to delete document in this team';
    end if;
    if old.created_by is distinct from auth.uid() then
      raise exception 'Only the creator can delete a document';
    end if;
  end if;

  return new;
end;
$$;

create trigger enforce_document_team
before insert or update or delete on public.documents
for each row execute function public.enforce_document_team();
