returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.file_shares
    where file_id = p_file_id
      and shared_with = p_shared_with
      and (expires_at is null or expires_at > now())
  );
$$;

create or replace function public.is_account_active()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.accounts
    where user_id = auth.uid()
      and not suspended
  );
$$;

create policy "accounts_select_own"
on public.accounts
for select
to authenticated
using (user_id = auth.uid());

create policy "files_select_own_or_shared"
on public.files
for select
to authenticated
using (
  owner_id = auth.uid()
