create policy "invoices_select_own_or_finance"
on public.invoices
for select
to authenticated
using (
  created_by = auth.uid()
  or public.is_finance_staff()
);

create policy "invoices_insert_own_draft"
on public.invoices
for insert
to authenticated
with check (
  created_by = auth.uid()
  and status = 'draft'
);

create or replace function public.invoices_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.created_by is distinct from auth.uid() then
      raise exception 'created_by must match auth.uid()';
    end if;
    if new.status <> 'draft' then
      raise exception 'new invoices must be draft';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.id is distinct from old.id
       or new.created_by is distinct from old.created_by then
      raise exception 'id and created_by are immutable';
    end if;
    if old.status <> 'draft' then
      if auth.is_finance_staff() then
        if old.status = 'sent'
           and new.status in ('paid', 'void') then
          if new.customer is distinct from old.customer
             or new.amount is distinct from old.amount then
            raise exception 'customer and amount are immutable';
          end if;
        else
          raise exception 'invalid status transition from %', old.status;
        end if;
      else
        if old.status <> 'draft' then
          raise exception 'only draft invoices can be modified';
        end if;
        if new.status not in ('draft', 'sent') then
          raise exception 'invalid status transition';
        end if;
        if new.customer is distinct from old.customer
           or new.amount is distinct from old.amount then
          raise exception 'customer and amount are immutable';
        end if;
