create or replace function public.reservation_guard()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.user_id is distinct from auth.uid() then
      raise exception 'reservations.user_id must match auth.uid()';
    end if;
    if new.reserved_for <= now() then
      raise exception 'reservation time must be in the future';
    end if;
    if new.status <> 'booked' then
      raise exception 'new reservations must be booked';
    end if;
    if not exists (
      select 1
      from public.restaurants
      where id = new.restaurant_id
    ) then
      raise exception 'restaurant does not exist';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.restaurant_id is distinct from old.restaurant_id
       or new.user_id is distinct from old.user_id
       or new.reserved_for is distinct from old.reserved_for
       or new.party_size is distinct from old.party_size then
      raise exception 'only status may be changed';
    end if;

    if auth.role() = 'authenticated' then
      if old.user_id <> auth.uid() then
        raise exception 'not allowed';
      end if;
      if old.status <> 'booked' then
        raise exception 'only booked reservations can be cancelled';
      end if;
      if old.reserved_for <= now() then
        raise exception 'reservation time has passed';
      end if;
      if new.status <> 'cancelled' then
        raise exception 'status must be cancelled';
      end if;
    elsif public.is_restaurant_staff(old.restaurant_id) then
      if old.status <> 'booked' then
        raise exception 'reservation is not booked';
      end if;
      if old.reserved_for > now() then
        raise exception 'reservation time has not passed';
      end if;
      if new.status not in ('seated', 'no_show') then
        raise exception 'staff can only mark as seated or no_show';
      end if;
    else
      raise exception 'not allowed';
    end if;
  end if;

  return new;
end
$$;

