alter table public.projects enable row level security;
alter table public.project_members enable row level security;
alter table public.issues enable row level security;

create or replace function public.is_project_member(p_project_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.project_members
    where project_id = p_project_id
      and user_id = auth.uid()
  );
$$;

create or replace function public.is_project_maintainer(p_project_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.project_members
    where project_id = p_project_id
      and user_id = auth.uid()
      and role = 'maintainer'
  );
$$;

create or replace function public.can_see_issue(p_issue_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.issues i
    join public.project_members pm on pm.project_id = i.project_id
    where i.id = p_issue_id
      and pm.user_id = auth.uid()
      and (
        i.is_confidential = false
        or pm.role = 'maintainer'
        or i.reporter_id = auth.uid()
        or i.assignee_id = auth.uid()
      )
  );
$$;

create or replace function public.issues_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'open' then
      raise exception 'new issues must be open';
    end if;
    if new.reporter_id is distinct from auth.uid() then
      raise exception 'reporter must be the current user';
    end if;
    if new.project_id not in (
      select project_id
      from public.project_members
      where user_id = auth.uid()
    ) then
      raise exception 'not a member of this project';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.id is distinct from old.id
       or new.project_id is distinct from old.project_id
       or new.reporter_id is distinct from old.reporter_id then
      raise exception 'immutable fields';
    end if;
    if old.is_confidential <> new.is_confidential
       and auth.role() <> 'service_role'
       and not exists (
         select 1
         from public.project_members
         where project_id = old.project_id
           and user_id = auth.uid()
           and role = 'maintainer'
       ) then
      raise exception 'only maintainers can change confidentiality';
    end if;
    if not exists (
      select 1
      from public.project_members pm
      join public.issues i on i.project_id = pm.project_id
      where i.id = old.id
        and pm.user_id = auth.uid()
        and (
          i.is_confidential = false
          or pm.role = 'maintainer'
          or i.reporter_id = auth.uid()
          or i.assignee_id = auth.uid()
        )
    ) then
      raise exception 'not allowed to update this issue';
    end if;
    if new.status not in ('open', 'in_progress', 'closed') then
      raise exception 'invalid status';
    end if;
  end if;

  return new;
end
$$;

create trigger issues_guard
before insert or update on public.issues
for each row execute function public.issues_guard();

create policy projects_select on public.projects
for select to authenticated
using (public.is_project_member(id));

create policy project_members_select on public.project_members
for select to authenticated
using (public.is_project_member(project_id));

create policy issues_select on public.issues
for select to authenticated
using (
  public.is_project_member(project_id)
  and (
    is_confidential = false
    or auth.role() = 'service_role'
    or public.is_project_maintainer(project_id)
    or reporter_id = auth.uid()
    or assignee_id = auth.uid()
  )
);

create policy issues_insert on public.issues
for insert to authenticated
with check (
  reporter_id = auth.uid()
  and status = 'open'
  and public.is_project_member(project_id)
);

create policy issues_update on public.issues
for update to authenticated
using (
  public.is_project_member(project_id)
  and (
    is_confidential = false
    or public.is_project_maintainer(project_id)
    or reporter_id = auth.uid()
    or assignee_id = auth.uid()
  )
)
with check (
  public.is_project_member(project_id)
  and (
    is_confidential = false
    or public.is_project_maintainer(project_id)
    or reporter_id = auth.uid()
    or assignee_id = auth.uid()
  )
);

revoke insert, update, delete on public.projects from anon, authenticated;
revoke insert, update, delete on public.project_members from anon, authenticated;
revoke delete on public.issues from anon, authenticated;
grant select on public.projects, public.project_members, public.issues to authenticated;
grant insert, update on public.issues to authenticated;
