create or replace function public.can_edit_segment(p_segment_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.segments s
    join public.translators t on t.project_id = s.project_id
       and t.lang = s.lang
    where s.id = p_segment_id
      and s.status = 'draft'
      and auth.uid() = t.user_id
  );
$$;

create or replace function public.segments_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if new.id is distinct from old.id
       or new.project_id is distinct from old.project_id
       or new.lang is distinct from old.lang
       or new.source_text is distinct from old.source_text then
      raise exception 'segment key and source text are immutable';
    end if;

    if old.status = 'reviewed' then
      raise exception 'reviewed segments are locked';
    end if;

    if auth.uid() is distinct from old.translated_by then
      raise exception 'translated_by is immutable';
    end if;

    if not exists (
      select 1
      from public.translators t
      where t.project_id = old.project_id
        and t.user_id = auth.uid()
        and t.lang = old.lang
    ) then
      raise exception 'not assigned to this project/language';
    end if;

    if old.status = 'draft' then
      if not exists (
        select 1
        from public.translators t
        where t.project_id = old.project_id
          and t.user_id = auth.uid()
          and t.lang = old.lang
          and t.role = 'translator'
      ) then
        raise exception 'only translators can edit draft segments';
      end if;

      if new.translated_by is distinct from auth.uid() then
        raise exception 'translator must record themselves';
      end if;

      if new.status <> 'draft' then
        raise exception 'draft segments can only stay draft';
      end if;
    elsif old.status = 'reviewed' then
      if not exists (
        select 1
        from public.translators t
        where t.project_id = old.project_id
          and t.user_id = auth.uid()
          and t.lang = old.lang
          and t.role = 'reviewer'
      ) then
        raise exception 'only reviewers can review';
      end if;

      if new.status <> 'reviewed' then
        raise exception 'segment status can only change to reviewed';
      end if;
    end if;
  elsif tg_op = 'INSERT' then
    raise exception 'segments can only be created by the server';
  end if;

  return new;
end;
$$;

