create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_status text;
begin
  update public.envelopes
     set status = 'completed'
   where id = p_envelope_id
     and status = 'sent'
     and not exists (
       select 1
       from public.envelope_recipients r
       where r.envelope_id = p_envelope_id
         and r.signed_at is null
     )
  returning status into v_status;

  if not found then
    raise exception 'Envelope % is not available for signing', p_envelope_id;
  end if;

  if not exists (
    select 1
    from public.envelope_recipients
    where envelope_id = p_envelope_id
      and user_id = auth.uid()
  ) then
    raise exception 'Caller is not a recipient of envelope %', p_envelope_id;
  end if;

  if exists (
    select 1
    from public.envelope_recipients
    where envelope_id = p_envelope_id
      and user_id = auth.uid()
      and signed_at is not null
  ) then
    raise exception 'Already signed envelope %', p_envelope_id;
  end if;

  if (
    select sign_order
    from public.envelope_recipients
    where envelope_id = p_envelope_id
      and user_id = auth.uid()
  ) > 1 then
    if exists (
      select 1
      from public.envelope_recipients
      where envelope_id = p_envelope_id
        and sign_order = (
          select min(sign_order)
          from public.envelope_recipients
          where envelope_id = p_envelope_id
            and signed_at is null
        )
        and signed_at is null
    ) then
      raise exception 'Earlier recipient has not signed yet';
    end if;
  end if;

  update public.envelope_recipients
     set signed_at = now()
   where envelope_id = p_envelope_id
     and user_id = auth.uid()
     and signed_at is null;

  select status
    into v_status
    from public.envelopes
   where id = p_envelope_id;

  return v_status;
end
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_status text;
begin
  update public.envelopes
     set status = 'voided'
   where id = p_envelope_id
     and sender_id = auth.uid()
     and status = 'sent'
  returning status into v_status;

  if not found then
    raise exception 'Envelope % cannot be voided', p_envelope_id;
  end if;

  select status
    into v_status
    from public.envelopes
   where id = p_envelope_id;

  return v_status;
end
$$;

