create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_status text;
begin
  select e.status
    into v_status
    from public.envelopes e
   where e.id = p_envelope_id
   for update;

  if not found then
    raise exception 'Envelope % not found', p_envelope_id;
  end if;

  if v_status <> 'sent' then
    raise exception 'Envelope % is not open for signing', p_envelope_id;
  end if;

  if auth.uid() not in (
    select user_id
      from public.envelope_recipients
     where envelope_id = p_envelope_id
  ) then
    raise exception 'Caller is not a recipient of envelope %', p_envelope_id;
  end if;

  if exists (
    select 1
      from public.envelope_recipients
     where envelope_id = p_envelope_id
       and user_id = auth.uid()
       and signed_at is not null
  ) then
    raise exception 'Caller has already signed envelope %', p_envelope_id;
  end if;

  if exists (
    select 1
      from public.envelope_recipients
     where envelope_id = p_envelope_id
       and sign_order < (
         select sign_order
           from public.envelope_recipients
          where envelope_id = p_envelope_id
            and user_id = auth.uid()
       )
       and signed_at is null
  ) then
    raise exception 'An earlier recipient has not signed yet';
  end if;

  update public.envelope_recipients
     set signed_at = now()
   where envelope_id = p_envelope_id
     and user_id = auth.uid();

  if not exists (
    select 1
      from public.envelope_recipients
     where envelope_id = p_envelope_id
       and signed_at is null
  ) then
    update public.envelopes
       set status = 'completed'
     where id = p_envelope_id;
  end if;

  select status
    into v_status
    from public.envelopes
   where id = p_envelope_id;

  return v_status;
end
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_sender uuid;
  v_status text;
begin
  select e.sender_id, e.status
    into v_sender, v_status
    from public.envelopes e
   where e.id = p_envelope_id
   for update;

  if not found then
    raise exception 'Envelope % not found', p_envelope_id;
  end if;

  if auth.uid() <> v_sender then
    raise exception 'Only the sender can void envelope %', p_envelope_id;
  end if;

  if v_status <> 'sent' then
    raise exception 'Envelope % is not sent', p_envelope_id;
  end if;

  update public.envelopes
     set status = 'void'
   where id = p_envelope_id;

  select status
    into v_status
    from public.envelopes
   where id = p_envelope_id;

  return v_status;
end
$$;

