create or replace function public.permits_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.revoked then
      raise exception 'new permits cannot be revoked';
    end if;
    if new.valid_until < current_date then
      raise exception 'valid_until must be today or later';
    end if;
    if new.valid_until > current_date + interval '365 days' then
      raise exception 'valid_until must be within 365 days';
    end if;
    if not exists (
      select 1
      from public.residents
      where unit_id = new.unit_id
        and user_id = auth.uid()
    ) then
      raise exception 'not allowed';
    end if;
    if (
      select count(*)
      from public.permits
      where unit_id = new.unit_id
        and not revoked
        and valid_until >= current_date
    ) >= 2 then
      raise exception 'unit has reached the active permit limit';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.revoked is distinct from old.revoked
       and auth.role() not in ('hoa_admin', 'service_role')
    then
      raise exception 'only admins can revoke permits';
    end if;
    if new.unit_id is distinct from old.unit_id
       or new.valid_until is distinct from old.valid_until
       or new.revoked is distinct from old.revoked
    then
      raise exception 'only the plate may be changed';
    end if;
    if auth.role() = 'resident' then
      if not exists (
        select 1
        from public.residents
        where unit_id = old.unit_id
          and user_id = auth.uid()
      ) then
        raise exception 'not allowed';
      end if;
    elsif auth.role() = 'hoa_admin' then
      if not exists (
        select 1
        from public.hoa_admins
        where user_id = auth.uid()
      ) then
        raise exception 'not allowed';
      end if;
    else
      raise exception 'not allowed';
    end if;
  end if;

  return new;
end
$$;

